import { describe, it, expect, jest, beforeEach } from '@jest/globals';
import { MockRegistry } from '../mocks/registry';

describe('Mock Validation Test', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should create mock OpenAI instance', () => {
    const mockOpenAI = MockRegistry.openai.create();
    
    expect(mockOpenAI).toBeDefined();
    expect(mockOpenAI.embeddings).toBeDefined();
    expect(mockOpenAI.embeddings.create).toBeDefined();
    expect(mockOpenAI.chat).toBeDefined();
    expect(mockOpenAI.chat.completions).toBeDefined();
    expect(mockOpenAI.chat.completions.create).toBeDefined();
  });

  it('should create mock fetch', () => {
    const mockFetch = MockRegistry.fetch.create();
    
    expect(mockFetch).toBeDefined();
    expect(typeof mockFetch).toBe('function');
  });

  it('should create mock Prisma', () => {
    const mockPrisma = MockRegistry.prisma.create();
    
    expect(mockPrisma).toBeDefined();
    expect(mockPrisma.student).toBeDefined();
    expect(mockPrisma.student.findFirst).toBeDefined();
    expect(mockPrisma.curriculumExpectation).toBeDefined();
  });

  it('should mock OpenAI embeddings correctly', async () => {
    const mockOpenAI = MockRegistry.openai.create();
    
    const result = await mockOpenAI.embeddings.create({
      input: 'test text',
      model: 'text-embedding-ada-002'
    });
    
    expect(result).toBeDefined();
    expect(result.data).toBeDefined();
    expect(result.data[0].embedding).toBeDefined();
    expect(result.data[0].embedding.length).toBe(1536);
  });

  it('should mock OpenAI chat correctly', async () => {
    const mockOpenAI = MockRegistry.openai.create({
      chat: { response: 'Test response from AI' }
    });
    
    const result = await mockOpenAI.chat.completions.create({
      model: 'gpt-4',
      messages: [{ role: 'user', content: 'test' }]
    });
    
    expect(result).toBeDefined();
    expect(result.choices).toBeDefined();
    expect(result.choices[0].message.content).toBe('Test response from AI');
  });
});